		}
	}

	// shift-show S002 进行中：当前事项 I006 显示未关闭（不带残留关闭信息）。
	rep2, _ := svc.ShiftReport("S002")
	r2 := FormatReport(rep2)
	if !strings.Contains(r2, "[未关闭]") || strings.Contains(r2, "残留人") {
