package handover

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

func TestScratchCloseInfoMissing(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "data.json")
	zero := time.Time{}
	real := tsDay(3, 10, 30)
	closedAt := tsDay(2, 16, 0)
	createdAt := tsDay(2, 8, 0)

	data := Data{
		ShiftSeq: 3,
		ItemSeq:  7,
		Shifts: []Shift{
			// S001 已结束、有结束时记录；S002 进行中；S003 旧数据缺结束时记录
			{ID: "S001", Position: "调度", Owner: "张三", Start: tsDay(2, 8, 0), End: tsDay(2, 16, 0),
				CreatedAt: createdAt, Closed: true, ClosedAt: &closedAt,
				CloseRecord: &ShiftCloseRecord{Items: []CloseItemSnapshot{
					// 结束时已关闭、关闭人与时间都缺
					{ItemID: "I001", Content: "甲", Severity: SeverityNormal, FollowOwner: "王五",
						Closed: true},
					// 结束时已关闭、只有关闭人
					{ItemID: "I002", Content: "乙", Severity: SeverityImportant, FollowOwner: "赵六",
						Closed: true, CloseOperator: "李四"},
					// 结束时已关闭、只有真实时间
					{ItemID: "I003", Content: "丙", Severity: SeverityUrgent, FollowOwner: "钱七",
						Closed: true, ClosedAt: &real},
					// 结束时已关闭、零值时间
					{ItemID: "I004", Content: "丁", Severity: SeverityNormal, FollowOwner: "孙八",
						Closed: true, CloseOperator: "周九", ClosedAt: &zero},
					// 结束时未关闭，后班关闭（缺关闭人与时间）
					{ItemID: "I005", Content: "戊", Severity: SeverityNormal, FollowOwner: "吴十"},
				}}},
			{ID: "S002", Position: "调度", Owner: "李四", Start: tsDay(2, 16, 0), End: tsDay(2, 23, 0),
				CreatedAt: closedAt},
			{ID: "S003", Position: "巡检", Owner: "郑十一", Start: tsDay(1, 8, 0), End: tsDay(1, 16, 0),
				CreatedAt: createdAt, Closed: true, ClosedAt: &closedAt},
		},
		Items: []Item{
			// I001 当前仍关闭，关闭人与时间都缺
			{ID: "I001", OriginShiftID: "S001", ShiftIDs: []string{"S001"}, CurrentShiftID: "S001",
				Content: "甲", Severity: SeverityNormal, FollowOwner: "王五", CreatedAt: createdAt,
				Closed: true},
			// I002 只有关闭人
			{ID: "I002", OriginShiftID: "S001", ShiftIDs: []string{"S001"}, CurrentShiftID: "S001",
				Content: "乙", Severity: SeverityImportant, FollowOwner: "赵六", CreatedAt: createdAt,
				Closed: true, CloseOperator: "李四"},
			// I003 只有真实时间
			{ID: "I003", OriginShiftID: "S001", ShiftIDs: []string{"S001"}, CurrentShiftID: "S001",
				Content: "丙", Severity: SeverityUrgent, FollowOwner: "钱七", CreatedAt: createdAt,
				Closed: true, ClosedAt: &real},
			// I004 零值时间
			{ID: "I004", OriginShiftID: "S001", ShiftIDs: []string{"S001"}, CurrentShiftID: "S001",
				Content: "丁", Severity: SeverityNormal, FollowOwner: "孙八", CreatedAt: createdAt,
				Closed: true, CloseOperator: "周九", ClosedAt: &zero},
			// I005 结束时未关闭，后来在 S002 关闭，但关闭人/时间缺失
			{ID: "I005", OriginShiftID: "S001", ShiftIDs: []string{"S001", "S002"}, CurrentShiftID: "S002",
				Content: "戊", Severity: SeverityNormal, FollowOwner: "吴十", CreatedAt: createdAt,
				Closed: true},
			// I006 未关闭，但旧数据残留关闭人与时间：仍按未关闭展示
			{ID: "I006", OriginShiftID: "S002", ShiftIDs: []string{"S002"}, CurrentShiftID: "S002",
				Content: "己", Severity: SeverityNormal, FollowOwner: "冯十二", CreatedAt: createdAt,
				Closed: false, CloseOperator: "残留人", ClosedAt: &real},
			// I007 旧数据班次 S003 的事项，当前已关闭、信息齐全
			{ID: "I007", OriginShiftID: "S003", ShiftIDs: []string{"S003"}, CurrentShiftID: "S003",
				Content: "庚", Severity: SeverityNormal, FollowOwner: "陈十三", CreatedAt: createdAt,
				Closed: true, CloseOperator: "王五", ClosedAt: &real},
		},
	}
	raw, err := json.Marshal(data)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, raw, 0o644); err != nil {
		t.Fatal(err)
	}
	store, err := Open(path)
	if err != nil {
		t.Fatal(err)
	}
	svc := NewService(store)

	checks := map[string][]string{
		"I002": {"[已关闭（关闭人 李四，关闭时间未记录）]"},
		"I003": {"[已关闭（关闭人未记录，关闭时间 " + fmtTime(real) + "）]"},
		"I004": {"[已关闭（关闭人 周九，关闭时间未记录）]"},
		"I005": {"[已关闭（关闭人未记录，关闭时间未记录）]"},
	}
	for id, wants := range checks {
		j, err := svc.ItemJourney(id)
		if err != nil {
			t.Fatalf("journey %s: %v", id, err)
		}
		text := FormatItemJourney(j)
		for _, w := range wants {
			if !strings.Contains(text, w) {
				t.Errorf("item-show %s 缺少 %q，实际：\n%s", id, w, text)
			}
		}
	}

	// I006 未关闭：残留值不作为有效关闭。
	j6, _ := svc.ItemJourney("I006")
	text6 := FormatItemJourney(j6)
	if !strings.Contains(text6, "[未关闭]") || strings.Contains(text6, "已关闭") {
		t.Errorf("未关闭事项残留值不应显示为关闭：\n%s", text6)
	}

	// shift-show S001：结束时记录与最新状态对照。
	rep1, err := svc.ShiftReport("S001")
	if err != nil {
		t.Fatal(err)
	}
	r1 := FormatReport(rep1)
	wantPairs := []string{
		"结束时已关闭（关闭人未记录，关闭时间未记录）",
		"结束时已关闭（关闭人 李四，关闭时间未记录）",
		"结束时已关闭（关闭人未记录，关闭时间 " + fmtTime(real) + "）",
		"结束时已关闭（关闭人 周九，关闭时间未记录）",
		// I005 结束时未关闭，最新状态对照中才显示当前关闭信息（含缺项）
		"结束时未关闭",
		"最新关闭情况=已关闭（关闭人未记录，关闭时间未记录）",
	}
	for _, w := range wantPairs {
		if !strings.Contains(r1, w) {
			t.Errorf("shift-show S001 缺少 %q，实际：\n%s", w, r1)
		}
	}

	// shift-show S002 进行中：当前事项 I006 显示未关闭（不带残留关闭信息）。
	rep2, _ := svc.ShiftReport("S002")
	r2 := FormatReport(rep2)
	if !strings.Contains(r2, "[未关闭]") || strings.Contains(r2, "残留人") {
		t.Errorf("进行中班次当前事项不应展示残留关闭人：\n%s", r2)
	}

	// shift-show S003 旧数据：历史不完整提示，只展示当前关闭情况。
	rep3, _ := svc.ShiftReport("S003")
	r3 := FormatReport(rep3)
	if !strings.Contains(r3, "历史记录不完整") ||
		!strings.Contains(r3, "已关闭（王五 于 "+fmtTime(real)+"）") {
		t.Errorf("旧班次应提示历史不完整并展示当前关闭情况：\n%s", r3)
	}
	if strings.Contains(r3, "结束时已关闭") {
		t.Errorf("旧班次不能把当前关闭信息当成结束时记录：\n%s", r3)
	}
}

